/* Lesson quizzes — batch 7 */
window.LQ=window.LQ||{};
Object.assign(window.LQ,{
"p15m1":[
 {id:"p15m1q1", q:"On x86-64 Linux, what does sizeof return for struct { char a; double d; char b; }, and what does it return after reordering the fields to double d; char a; char b;?", options:["24, then 16","10, then 10","24, then 10","16, then 16"], answer:0, why:"d must sit at a multiple of 8, so a is followed by 7 padding bytes, d occupies 8 to 15, b sits at 16 and the size rounds up to 24. Reordered, the two chars share the tail and the total pads to 16. 10 ignores padding entirely."},
 {id:"p15m1q2", q:"uint8_t a = 250, b = 10; int s = a + b; uint8_t t = a + b; What are s and t?", options:["s = 4, t = 4","Both lines are undefined behavior because the sum overflows","s = 260, t = 4","s = 260, t = 255"], answer:2, why:"Both operands are promoted to int before the addition, so the expression is 260 and fits in s. Storing 260 into a uint8_t wraps modulo 256 to 4. No signed type overflows, so there is no undefined behavior; unsigned wraparound is defined."},
 {id:"p15m1q3", q:"void total(int a[10]) { size_t n = sizeof(a) / sizeof(a[0]); ... } is called with a real ten-int array on 64-bit Linux. What is n inside the function?", options:["10","2","1","40"], answer:1, why:"An array parameter is really a pointer, so sizeof(a) is 8 (the pointer), not 40, and 8 / 4 gives 2. The [10] in the declaration is ignored, which is why C functions must be passed the length separately."},
 {id:"p15m1q4", q:"Code that stores file sizes in a long works on 64-bit Linux, but the same code built with MSVC on 64-bit Windows breaks on files larger than about 2 GB. What is the cause and the fix?", options:["Windows stores integers big-endian; swap the bytes with htonl before use","Plain char is unsigned on Windows; declare the buffers as signed char","Pointers are 4 bytes on Windows; compile for a 64-bit target instead","Windows uses LLP64, where long is 4 bytes; use int64_t from stdint.h"], answer:3, why:"Linux is LP64 (long is 8 bytes) while Windows is LLP64 (long is 4 bytes), so values above 2,147,483,647 no longer fit. Exact-width types such as int64_t fix the width on every platform. Pointers on 64-bit Windows are 8 bytes, so that is not the cause."},
 {id:"p15m1q5", q:"gcc -c main.c and gcc -c util.c both succeed. Then gcc main.o -o app fails with: undefined reference to `parse_config`, a function util.c defines. Which stage failed, and what fixes it?", options:["The preprocessor; main.c is missing the #include for util.h","The compiler proper; declare parse_config before calling it","The linker; util.o was never given to it, so run gcc main.o util.o -o app","The assembler; regenerate util.s with gcc -S and assemble it again"], answer:2, why:"An undefined reference is a link error: every file compiled, but the linker was handed only main.o and cannot resolve the symbol. A missing header or declaration shows up at the compile stage as a warning or error, not as an undefined reference."}
],
"p15m2":[
 {id:"p15m2q1", q:"Using glibc's chunk arithmetic on 64-bit Linux, how many bytes of heap do malloc(40) and malloc(1) each consume?", options:["40 and 1","48 and 32","64 and 32","48 and 16"], answer:1, why:"A chunk is (n + 8) rounded up to a multiple of 16, with a 32-byte minimum. 40 + 8 = 48, already a multiple of 16; 1 + 8 = 9 would round to 16, but the minimum lifts it to 32. Adding a full 16 bytes to the request gives the wrong 64."},
 {id:"p15m2q2", q:"A function contains: int x = read_count(); if (x + 100 < x) { log_overflow(); return -1; } Built with GCC at -O2, what is the most likely result?", options:["The check works, because C23 mandates two's complement, so overflow wraps","The compiler turns the check into a run-time trap that aborts on overflow","The check works on x86 only, because x86 wraps signed integers in hardware","The compiler deletes the check, since signed overflow is undefined behavior"], answer:3, why:"The optimizer may assume undefined behavior never occurs, so x + 100 < x is treated as always false and removed. C23 fixed the representation as two's complement, but signed overflow is still undefined. A run-time report only appears if you ask for it with -fsanitize=undefined."},
 {id:"p15m2q3", q:"ASan prints: heap-buffer-overflow ... READ of size 4 ... located 0 bytes after 40-byte region, allocated at stats.c:12. Line 12 is int *v = malloc(10 * sizeof *v); What is the bug?", options:["A loop reads v[10], one past the end; the bound should be i < 10","v was freed earlier and then read, so this is a use-after-free","The program freed v twice, corrupting the next chunk's header","Deep recursion overflowed the stack down into the heap region"], answer:0, why:"The region is 40 bytes (ten 4-byte ints) and a 4-byte read lands exactly at its end, which is index 10: the classic <= off-by-one. A use-after-free would be reported as heap-use-after-free together with the stack of the free, not as a read past the region."},
 {id:"p15m2q4", q:"checksec on your service reports: Canary found, NX enabled, No PIE, Partial RELRO. Which change closes a real gap?", options:["Disable NX so the stack canary can check the frame more reliably","None; a canary plus NX already makes stack overflows harmless","Rebuild with -fPIE -pie and full RELRO (-z relro -z now)","Set randomize_va_space to 0 so crashes reproduce in production"], answer:2, why:"Without PIE, ASLR cannot move the program's own code, so its addresses stay predictable, and partial RELRO leaves the dynamic-linking table writable. Mitigations are layered because each has bypasses on its own, which is why canary plus NX is not enough."},
 {id:"p15m2q5", q:"A long-running daemon mallocs and frees thousands of 2 KiB buffers during a traffic burst. Afterwards its resident memory stays near the peak, yet Valgrind reports no leaks. What explains it?", options:["Valgrind cannot see leaks in long-running processes, so a leak is likely","glibc keeps freed small chunks on its free lists instead of returning them","free() is asynchronous; the kernel reclaims the pages about 30 seconds later","The buffers were placed on the stack, which never shrinks once it grows"], answer:1, why:"glibc keeps freed small chunks in its bins (tcache, fast, small and so on) so the same process can reuse them; only mmap'd allocations of 128 KiB or more go straight back to the kernel. High resident memory without a leak is normal allocator behavior."}
],
"p15m3":[
 {id:"p15m3q1", q:"One container job ends with exit code 137 and another with 143. What is the most plausible reading of each?", options:["137: command not found; 143: found but not executable","Both are ordinary failure codes the programs chose to return","137: SIGKILL, often the OOM killer; 143: SIGTERM","137: segmentation fault (SIGSEGV); 143: interrupted by Ctrl-C (SIGINT)"], answer:2, why:"The shell reports 128 + N for death by signal N: 137 - 128 = 9 (SIGKILL, typical of the out-of-memory killer) and 143 - 128 = 15 (SIGTERM). Not found is 127 and not executable 126; a segfault would be 139 and Ctrl-C 130."},
 {id:"p15m3q2", q:"In your tiny shell, cd is handled like ls: fork, then the child calls chdir(argv[1]) and exits. After cd /tmp, pwd still prints the old directory. Why?", options:["chdir changed only the child's directory; cd must run inside the shell itself","chdir needs root privileges, so it fails silently when run in a child","The child should exec the cd program instead, so the kernel updates the parent","waitpid restores the parent's original directory when it reaps the child"], answer:0, why:"The working directory is per-process state. A forked child has its own copy, so changing it affects nobody once the child exits. That is why cd, exit and export are builtins that run inside the shell without forking."},
 {id:"p15m3q3", q:"A tool writes a 1 MB report with write(1, &c, 1) for each byte, and strace -c shows about 1,000,000 write calls. At about 200 ns per system call round trip, how much time goes to crossing into the kernel, and what is the fix?", options:["About 0.2 ms, which is negligible next to the disk time","About 200 s; rewrite the output loop in assembly to cut overhead","About 0.2 s; preload a library with LD_PRELOAD so write skips the kernel","About 0.2 s; buffer output so each write carries kilobytes"], answer:3, why:"1,000,000 × 200 ns = 0.2 seconds spent purely on boundary crossings. A 4–8 KiB stdio buffer cuts the count to a few hundred calls. LD_PRELOAD only swaps a library function; the bytes still have to reach the kernel through a system call."},
 {id:"p15m3q4", q:"A dynamically linked binary built on your workstation fails on a minimal server with: error while loading shared libraries: libfoo.so.2: cannot open shared object file. What is happening?", options:["The kernel rejected the file at execve because its ELF magic bytes are wrong","The loader cannot find a needed shared library; install it or fix the search path","Lazy PLT binding failed, so the first call into libfoo crashed the program","The binary was built with -O3, which the server's CPU cannot execute"], answer:1, why:"The kernel accepted the ELF and started the interpreter; ld-linux then searched the library paths for a DT_NEEDED entry and failed. ldd shows which libraries are missing, and a static build removes the dependency. Bad magic bytes would fail at execve with a different error."},
 {id:"p15m3q5", q:"ps shows dozens of <defunct> children under your server process, each holding a process-table slot. What is the correct fix?", options:["Send SIGKILL to each defunct process to force it out of the table","Make the children call _exit instead of exit so they leave no entry","Have the parent reap them with waitpid, e.g. from a SIGCHLD handler","Raise ulimit -n so more processes fit in the process table"], answer:2, why:"A zombie has already exited; it only waits for its parent to collect its status with wait or waitpid. SIGKILL does nothing to a process that is already dead, and _exit versus exit only changes buffer flushing. Reaping in the parent frees the slots."}
],
"p15m4":[
 {id:"p15m4q1", q:"Three CPU-bound tasks share one core under the fair scheduler: two at nice 0 (weight 1024) and one at nice 5 (weight 335). Roughly what share of the core does each get?", options:["About 33% each, since nice only matters for real-time tasks","About 50% for each nice-0 task and nothing for the nice-5 task until they finish","About 40%, 40% and 20%","About 43%, 43% and 14%"], answer:3, why:"Each share is the task's weight over the total weight: 1024 / 2383 ≈ 43% for each nice-0 task and 335 / 2383 ≈ 14% for the nice-5 task. A fair scheduler never starves the lighter task; it simply runs it proportionally less."},
 {id:"p15m4q2", q:"With 4 KiB pages and 4-level x86-64 paging, what are the page offset and the lowest-level page-table index for virtual address 0x403A10?", options:["Offset 0x3A10, index 0x40","Offset 0xA10, index 3","Offset 0xA10, index 1027","Offset 0x10, index 0x3A"], answer:1, why:"The low 12 bits are the offset, 0xA10. The next 9 bits are the index: 0x403A10 >> 12 = 0x403 = 1027, and 1027 mod 512 = 3. 1027 cannot be an index, because each table holds only 512 entries; the remaining bits select entries at the higher levels."},
 {id:"p15m4q3", q:"A CPU's second-level TLB has 1,536 entries. How much memory does it cover with 4 KiB pages, and with 2 MiB huge pages?", options:["6 MiB and 3 GiB","6 MiB and 6 GiB","1.5 MiB and 768 MiB","6 GiB and 3 TiB"], answer:0, why:"Reach is entries times page size: 1,536 × 4 KiB = 6,144 KiB = 6 MiB, and 1,536 × 2 MiB = 3,072 MiB = 3 GiB. That 512-fold jump is why huge pages help programs whose working set is far larger than a few megabytes."},
 {id:"p15m4q4", q:"vmstat 1 on a slow server shows si and so in the thousands every second, user CPU falling and the load average climbing. What is the best diagnosis?", options:["CPU saturation from the load; add more cores","A context-switch storm caused by a hot lock","Thrashing: the working set no longer fits in RAM","Healthy behavior: some swap use is normal on Linux"], answer:2, why:"Continuous heavy swap-in and swap-out while useful CPU work drops is the signature of thrashing. Some quiet swap use is normal, but a high, sustained swap-in rate is the problem. A switch storm would show in the cs column, not in si and so."},
 {id:"p15m4q5", q:"vmstat shows about 150,000 context switches per second, and you estimate a direct cost of about 4 µs per switch. How much CPU time per second does switching consume, and is it worth investigating?", options:["About 0.6 ms per second; negligible, so leave it alone","About 60 µs per second; negligible next to the workload","About 6 s per second, which is impossible, so the estimate must be wrong","About 0.6 CPU-seconds per second, 60% of a core; yes, investigate"], answer:3, why:"150,000 × 4 µs = 600,000 µs = 0.6 s of CPU every second, before the indirect cost of cold caches and TLB. A few thousand switches per second would cost under 1% of a core; this rate means something is thrashing."}
],
"p15m5":[
 {id:"p15m5q1", q:"A job is 90% parallelizable. Using Amdahl's law, what is its speedup on 8 cores, and what ceiling does it approach no matter how many cores you add?", options:["About 4.7×; ceiling 10×","About 7.2×; ceiling 10×","About 4.7×; no ceiling with enough cores","About 8×; ceiling 9×"], answer:0, why:"Speedup = 1 / (0.10 + 0.90 / 8) = 1 / 0.2125 ≈ 4.7. As the core count grows the parallel term vanishes, leaving 1 / 0.10 = 10×. Multiplying 0.9 by 8 to get 7.2 ignores the serial 10% that never shrinks."},
 {id:"p15m5q2", q:"A hung service: gdb thread apply all bt shows thread 1 waiting in lock(&ledger) while holding audit, and thread 2 waiting in lock(&audit) while holding ledger. Which fix removes the deadlock?", options:["Declare both mutexes volatile so each thread sees the other's update","Replace both mutexes with spinlocks so neither thread sleeps","Impose one global order: every code path takes ledger before audit","Add a short sleep before each lock so the threads rarely collide"], answer:2, why:"This is circular wait, one of Coffman's four conditions, and a global lock order makes a cycle impossible. Spinlocks still wait forever, only while burning CPU; volatile provides no synchronization; a sleep makes the deadlock rarer, not impossible."},
 {id:"p15m5q3", q:"Two consumer threads run: lock(m); if (q.count == 0) pthread_cond_wait(&cv, &m); item = pop(&q); unlock(m); Occasionally pop runs on an empty queue. What is the fix?", options:["Unlock m before calling pthread_cond_wait so the producer can get in","Change the if to a while, so the thread re-checks the condition after every wakeup","Use pthread_cond_broadcast instead of pthread_cond_signal in the producer","Make q.count an atomic integer"], answer:1, why:"Wakeups can be spurious, and the other consumer may take the item between the signal and this thread reacquiring the mutex, so only a re-check in a while loop is safe. pthread_cond_wait already releases the mutex atomically; unlocking first would add a race."},
 {id:"p15m5q4", q:"Four threads each add 1 to a shared total 10 million times. Which design gives the correct total in the least time?", options:["A mutex locked and unlocked around every increment","atomic_fetch_add on the shared total for every increment","A volatile int total that every thread increments directly","Local per-thread counters, added to the total once at the end"], answer:3, why:"Local counting needs no synchronization inside the loop and only four updates to shared state. Atomics and mutexes are correct but bounce the cache line or the lock on all 40 million increments, and volatile gives no atomicity, so updates are still lost."},
 {id:"p15m5q5", q:"On the default Python 3.14 build, eight threads resizing images on an 8-core PC run no faster than one thread, while eight threads downloading files do speed up. Why?", options:["The GIL lets one thread run bytecode; threads release it while waiting on I/O","Python threads are green threads multiplexed onto a single OS thread","The operating system pins every Python process to a single CPU core","Network threads receive a higher scheduler weight than CPU-bound ones"], answer:0, why:"CPython's global interpreter lock lets one thread execute Python code at a time, so CPU-bound threads take turns, while blocking I/O releases the lock. They are real OS threads; multiprocessing or the free-threaded 3.14t build gives true parallelism."}
],
"p15m6":[
 {id:"p15m6q1", q:"A cron job runs ./sync 2>&1 > sync.log, yet error messages keep arriving in cron's email instead of the log. Why, and what is the fix?", options:["cron ignores redirections; wrap the command in a shell script","2>&1 ran while fd 1 still pointed at cron; use > sync.log 2>&1","stderr is unbuffered and cannot be redirected; use 2>> instead","The log is opened with O_APPEND, which only applies to stdout"], answer:1, why:"Redirections apply left to right. 2>&1 makes fd 2 a copy of fd 1 as it is at that moment, the original output, and only afterwards is fd 1 pointed at the file. Putting > sync.log first sends both descriptors to the file."},
 {id:"p15m6q2", q:"df reports /var 100% full, but du -sh /var finds only 4 GB on a 50 GB volume. Earlier you deleted a 44 GB log while the service writing it kept running. What is going on?", options:["The volume has run out of inodes; confirm it with df -i","The ext4 journal is still holding the deleted log's blocks","The page cache is counting the log as used disk space","The service still holds the deleted file open; find it with lsof +L1"], answer:3, why:"rm removed only the name. The inode and its blocks live until the last open descriptor closes, so df counts them while du, which walks names, cannot see them. Inode exhaustion is real but shows in df -i, not as missing gigabytes."},
 {id:"p15m6q3", q:"A program writes 2,000 records, calling write and then fsync after each one. With fsync taking about 0.5 ms on NVMe and 12 ms on a hard drive, about how long does the run take on each?", options:["About 1 s on NVMe and 24 s on the hard drive","About 1 ms on NVMe and 24 ms on the hard drive","About 10 s on NVMe and 240 s on the hard drive","About the same on both, because write returns once data reaches the page cache"], answer:0, why:"2,000 × 0.5 ms = 1 s and 2,000 × 12 ms = 24 s. fsync waits for the device, so the drive's latency is paid on every record. The page-cache shortcut applies to write alone; calling fsync after each write removes it."},
 {id:"p15m6q4", q:"An editor saves a config file by truncating it, calling write() and close(), then showing Saved. A power cut a few seconds later leaves the file empty. Which save procedure is durable?", options:["Call fflush before close so the data reaches the disk","No change is needed, since ext4's default ordered mode journals file contents","Write a temporary file, fsync it, then rename it over the original","Make a hard link to the file before writing so the old version survives"], answer:2, why:"write and fflush only move data into the kernel's page cache; fsync forces it to the device. Writing a temporary file, fsyncing it and renaming it is an atomic replace, so a crash leaves the old or the new version. Ordered mode journals metadata, not contents."},
 {id:"p15m6q5", q:"In an empty directory you run: echo hi > a; ln a b; ln -s a c; rm a. What happens when you now read b and c?", options:["Both b and c still print hi","b still prints hi; c is a dangling symbolic link","Neither works, because rm freed the inode","b fails, but c works because a symbolic link stores the inode number"], answer:1, why:"A hard link is a second name for the same inode; rm drops its link count from 2 to 1, so the data survives under b. A symbolic link stores the path a, and that name no longer exists, so following c fails."}
],
"p15m7":[
 {id:"p15m7q1", q:"A Makefile has OBJS = main.o shell.o alloc.o, a rule shell: $(OBJS) that links them, and the pattern rule %.o: %.c shell.h. You edit only shell.h and run make. What gets rebuilt?", options:["Nothing, because make only compares .c files with .o files","Only shell.o, because its name matches the changed shell.h","main.o, shell.o and alloc.o are recompiled, then shell is relinked","Only the final link step runs, since no .c file changed"], answer:2, why:"The pattern rule lists shell.h as a prerequisite of every .o file, so all three objects are now older than a prerequisite and are recompiled; the executable then depends on newer objects and relinks. Make compares listed prerequisites, not similar names."},
 {id:"p15m7q2", q:"A benchmark sums one billion integers into a local variable that is never printed or returned. Built at -O2, it reports 0 ms. What happened?", options:["Dead-code elimination removed the loop because its result is never used","Auto-vectorization made the loop thousands of times faster","The CPU cache held the whole loop, so it took no measurable time","The timer resolution is too coarse; the loop actually ran at full length"], answer:0, why:"A result nobody uses is dead, and the optimizer deletes it together with everything that fed it. SIMD speeds a loop up by a small factor, never to zero. Consume the result, for example by printing it, so the work is real."},
 {id:"p15m7q3", q:"int g(int x) { return x * 4 + 7; } is compiled for x86-64 Linux at -O2. Which output is most likely?", options:["push rbp; mov rbp, rsp; imul eax, edi, 4; add eax, 7; pop rbp; ret","mov eax, DWORD PTR [rdi+4]; add eax, 7; ret","call a multiply helper routine, then add eax, 7; ret","lea eax, [rdi*4+7]; ret"], answer:3, why:"At -O2 there is no frame, the argument arrives in rdi per the System V convention, and x86 address arithmetic can scale by 4 and add 7 in one lea. The prologue-plus-multiply shape is closer to -O0, and [rdi+4] is a memory load such as a struct field."},
 {id:"p15m7q4", q:"During a long run, a global variable limit is mysteriously set to 0 somewhere in a 40,000-line program. Which GDB approach finds the line that writes it?", options:["break main, then step through the program until limit changes","watch limit, then continue; GDB stops at the write that changes it","display limit, which halts execution whenever the value changes","Wait for the crash, then use backtrace to see who changed limit"], answer:1, why:"A watchpoint stops execution the moment the watched location changes and shows the responsible line. display only prints the value whenever the program stops for some other reason, and a backtrace shows the current call chain, not an earlier write."},
 {id:"p15m7q5", q:"Which compiler stage reports each error? (a) stray '@' in program, (b) expected ';' before '}' token, (c) incompatible pointer type in assignment.", options:["(a) parser, (b) lexer, (c) linker","(a) preprocessor, (b) semantic analysis, (c) code generator","(a) lexer, (b) parser, (c) semantic analysis","(a) lexer, (b) semantic analysis, (c) parser"], answer:2, why:"A character that starts no valid token is caught when the lexer builds tokens; a missing semicolon breaks the grammar the parser follows; a type mismatch is found when semantic analysis checks types with the symbol table. The linker only resolves symbols."}
]
});
Object.assign(window.LQ,{
"p16m1":[
 {id:"p16m1q1", q:"After installing a third-party VPN client, a laptop bugchecks (blue screen) several times a day, while crashing applications such as Notepad only ever close themselves. What explains the difference?", options:["The VPN client runs as LocalSystem, and any LocalSystem crash halts Windows","It ships a kernel-mode driver, and a driver fault crashes the shared kernel","Notepad runs in Session 1 while the VPN runs in Session 0, and only Session 0 can bugcheck","Applications run under UAC's filtered token, which catches and contains their crashes"], answer:1, why:"Drivers run in kernel mode inside the same address space as ntoskrnl.exe, so a bad pointer in one corrupts the kernel and forces a bugcheck. A user-mode process, even a LocalSystem service, has its own address space, so its crash kills only that process."},
 {id:"p16m1q2", q:"Ana belongs to Contractors. The Reports folder carries an inherited Deny Write for Contractors from its parent, and the file Q3.xlsx inside it has an explicit Allow Write entry for Ana. Can Ana save changes to Q3.xlsx?", options:["No; Deny always beats Allow, whatever the level","No; inherited entries are evaluated first because they come from the parent","Only if she is also a member of local Administrators","Yes; an explicit entry beats an inherited one, and Deny wins only at the same level"], answer:3, why:"Windows evaluates explicit entries before inherited ones, so the explicit Allow on the file is reached before the inherited Deny. Deny beats Allow only when both sit at the same level, so 'Deny always wins' is the tempting but wrong rule."},
 {id:"p16m1q3", q:"A backup agent service must read local files and authenticate to a file server under its own domain identity, and nobody should ever have to manage its password. Which account fits?", options:["A group Managed Service Account (gMSA)","LocalSystem","LocalService","A domain user account whose password never expires"], answer:0, why:"A gMSA has its own domain identity, holds only the rights you grant, and AD rotates its random password automatically. LocalSystem has more local power than Administrator and appears on the network as the computer account; LocalService is anonymous on the network."},
 {id:"p16m1q4", q:"Ana is a local administrator. In a normal, non-elevated PowerShell window, writing a value under HKLM:\\SOFTWARE fails with access denied. Why?", options:["HKLM is writable only by LocalSystem, never by administrators","Her account lacks SeDebugPrivilege, which registry writes require","Her logon gave a filtered Medium token; writing needs the elevated one","Administrators must switch to kernel mode before they can change HKLM"], answer:2, why:"User Account Control gives an administrator two tokens: a filtered Medium token for everyday programs and a full High token that the consent prompt hands to elevated ones. Run the window as administrator and the write succeeds. Being an administrator never means running in kernel mode."},
 {id:"p16m1q5", q:"Only one user's logons are slow, the suspicious process returns after every reboot, and the HKLM Run keys look clean. Where is the persistence most likely, and which tool lists it?", options:["In HKCU\\...\\CurrentVersion\\Run for that user; Autoruns lists every auto-start location","In the HKLM Services key, since services start before logon; check services.msc","In a scheduled task; Process Explorer lists all scheduled tasks","In winlogon.exe's handle table; Task Manager's Details tab shows it"], answer:0, why:"An entry that fires only at one user's logon lives in that user's hive (NTUSER.DAT, loaded as HKCU), which is why the machine-wide keys look clean. Autoruns enumerates Run keys, services, tasks and other auto-starts in one view; Process Explorer shows what runs, not how it returns."}
],
"p16m2":[
 {id:"p16m2q1", q:"try { Get-Item C:\\Data\\missing.txt } catch { Write-Output 'File not found' } prints a red error and never prints File not found. Why, and what fixes it?", options:["catch only works inside a function marked [CmdletBinding()]","Get-Item returns $null for missing files, so there is nothing to catch","The error is non-terminating; add -ErrorAction Stop to Get-Item","Write-Output is suppressed inside catch blocks; use Write-Host"], answer:2, why:"Get-Item writes a non-terminating error to the error stream and execution continues, so try/catch sees nothing. -ErrorAction Stop promotes it to a terminating error, which catch handles. [CmdletBinding()] adds common parameters but does not change how catch works."},
 {id:"p16m2q2", q:"Which pipeline lists the five processes using the most memory, with name and working set in MB, as objects you could still export to CSV?", options:["Get-Process | Sort-Object WorkingSet64 -Descending | Select-Object -First 5 Name, @{n='MB';e={[math]::Round($_.WorkingSet64/1MB)}}","Get-Process | Format-Table Name, WorkingSet64 | Sort-Object WorkingSet64 -Descending | Select-Object -First 5","Get-Process | Out-String | Select-String 'WorkingSet' | Select-Object -First 5","Get-Process | Select-Object -First 5 | Sort-Object WorkingSet64 -Descending"], answer:0, why:"Sort on the WorkingSet64 property, then take five and compute an MB column; the output stays objects. Format-Table mid-pipeline emits formatting objects Sort cannot use, Out-String turns objects back into text, and taking five before sorting picks arbitrary processes."},
 {id:"p16m2q3", q:"Enter-PSSession SRV01 works with Kerberos. Inside that session, Get-ChildItem \\\\FS02\\Share fails with access denied, although your account has rights on FS02. What is happening, and what is the right fix?", options:["WinRM HTTPS port 5986 is closed on FS02; open it in FS02's firewall","Your account needs Domain Admin rights to reach a second machine from a session","Kerberos never works inside sessions; enable CredSSP everywhere so credentials are forwarded","It is the second hop; use resource-based constrained delegation or explicit credentials"], answer:3, why:"Remoting deliberately does not delegate your credential from SRV01 onward to FS02. Resource-based constrained delegation or an explicit -Credential solves it narrowly. Blanket CredSSP hands reusable credentials to the remote host, exactly the exposure the default avoids."},
 {id:"p16m2q4", q:"An audit report states: 'Execution policy is AllSigned on all servers, so malicious PowerShell cannot run.' What is the correct assessment?", options:["Correct, because AllSigned blocks every unsigned script for every user","Wrong: it prevents accidents only and is bypassed with one flag","Correct, as long as PowerShell 7 is not installed alongside it","Wrong only because RemoteSigned is stricter than AllSigned"], answer:1, why:"Execution policy is a safety feature, not a security boundary: anyone who can start PowerShell can bypass it for that process. Enforcement comes from App Control for Business and Constrained Language Mode, visibility from event 4104. RemoteSigned is looser than AllSigned, not stricter."},
 {id:"p16m2q5", q:"Your script runs the native tool icacls.exe and must branch on its numeric exit code, for example 2 versus 5. Coming from Bash, what should the script test?", options:["$?, which holds the numeric code just as it does in Bash","$Error[0].ExitCode, which records every native exit code","$LASTEXITCODE; in PowerShell $? is only true or false","The ExitCode property on the pipeline's output object"], answer:2, why:"In PowerShell $? is a boolean saying whether the last command succeeded, so it cannot tell 2 from 5. $LASTEXITCODE carries the numeric exit code of the last native program, the equivalent of Bash's $?."}
],
"p16m3":[
 {id:"p16m3q1", q:"A host has two 16-core processors and will run 10 Windows Server VMs. At $73.50 per Standard core and about $423 per Datacenter core, which edition is cheaper?", options:["Standard at $2,352, because one set of core licenses covers every VM on the host","Standard: about $11,760 for five sets, against about $13,540 for Datacenter","Datacenter, because it is always cheaper once you run more than two VMs","Datacenter at $6,771, because one 16-core pack covers the whole host"], answer:1, why:"32 cores × $73.50 = $2,352 licenses two VMs, so ten VMs need five sets: $11,760. Datacenter is 32 × $423.19 ≈ $13,542 for unlimited VMs. The crossover sits near twelve VMs, and a single 16-core pack covers only half of the 32 cores."},
 {id:"p16m3q2", q:"A training center's DHCP scope is a /24. It excludes .1 to .40 for infrastructure and holds 14 printer reservations. Each day 120 different visitor laptops arrive, and the lease is 8 days. What happens?", options:["214 dynamic leases; fine for almost two days, then lengthen the lease","254 leases; the scope comfortably lasts the whole week","200 dynamic leases; the scope lasts the full 8-day lease cycle","200 dynamic leases; exhausted on day two, so shorten the lease to 1 day"], answer:3, why:"254 usable addresses minus 40 excluded minus 14 reserved leaves 200. Two days of visitors need 240, and none of the 8-day leases has expired yet. A 1-day lease lets each day's addresses return. Forgetting the reservations gives the tempting 214."},
 {id:"p16m3q3", q:"FS-Finance-RW must modify and FS-Finance-RO must read \\\\fs01\\finance. Following the recommended Windows convention, how should the permissions be laid out?", options:["Share: Authenticated Users Full; NTFS: RW group Modify, RO group Read","Share: Everyone Read; NTFS: RW group Modify, RO group Read","Share: RW group Change, RO group Read; NTFS: Everyone Full Control","Share: Everyone Full; NTFS: Everyone Full; keep the share name hidden"], answer:0, why:"Effective access is the more restrictive of share and NTFS, so keep the share wide and put precise rights in NTFS, which also applies to local access. With Share: Everyone Read, the RW group would be capped at Read and could never save."},
 {id:"p16m3q4", q:"A new PC cannot join corp.example.com: 'An Active Directory Domain Controller for the domain could not be contacted.' Pinging the DC's IP works, and ipconfig /all shows DNS server 8.8.8.8. What is the fix?", options:["Open TCP and UDP port 88 on the domain controller's firewall","Authorize the DHCP server in Active Directory so the PC gets a lease","Point its DNS at the domain DNS servers, which hold the DC SRV records","Add the DC's IP address to the PC's hosts file as corp.example.com"], answer:2, why:"Clients find DCs through SRV records such as _ldap._tcp.dc._msdcs.corp.example.com, which exist only in the AD DNS zone, so a public resolver cannot answer. A hosts entry supplies one A record, not the SRV records the DC Locator needs."},
 {id:"p16m3q5", q:"On a Hyper-V lab host, the VMs must reach each other and the host but never the office LAN, and one VM is a Windows 11 client. Which switch and VM generation fit?", options:["Private switch; Generation 2 with a virtual TPM","Internal switch; Generation 2 with a virtual TPM","External switch; Generation 1","Internal switch; Generation 1 with Dynamic Memory"], answer:1, why:"An internal switch connects the VMs and the host only; a private switch would cut off the host too, and an external switch bridges onto the LAN. Windows 11 needs UEFI, Secure Boot and a TPM, which only a Generation 2 VM with a virtual TPM provides."}
],
"p16m4":[
 {id:"p16m4q1", q:"A domain GPO (not Enforced) sets the screen lock to 10 minutes, and a GPO on OU=Ops sets 20 minutes. The child OU=Ops/NOC has Block Inheritance and no GPO of its own. What lock setting does a NOC computer get from Group Policy?", options:["Neither: Block Inheritance stops both, so local policy applies","20 minutes, inherited from the nearest parent OU","10 minutes, because domain GPOs always win","10 minutes, because the stricter security setting is combined across GPOs"], answer:0, why:"Block Inheritance stops every GPO linked above the OU unless its link is Enforced, and neither is. With no GPO linked to NOC, the setting falls back to local policy. GPOs do not merge to the strictest value; precedence is last writer wins."},
 {id:"p16m4q2", q:"Users open an internal web app at http://reports.corp.example.com, a name with its own DNS A record pointing at server APP04. The DC logs 4776 events for these sign-ins and no 4769 service tickets. What is the most likely cause?", options:["The KDC on port 88 is down, so the whole domain uses NTLM","The users' TGTs are RC4-encrypted, which forces NTLM for web apps","No SPN exists for HTTP/reports.corp.example.com, so it falls back to NTLM","Group Policy has not refreshed on the clients in the last 90 minutes"], answer:2, why:"To get a service ticket the client asks for the SPN of the name it used. With no SPN for the alias, the ticket request fails and Windows silently uses NTLM, which the DC validates as event 4776; setspn -L shows an account's SPNs. A dead KDC would break all logons."},
 {id:"p16m4q3", q:"The DC holding the RID Master role has been offline for two weeks, and logons still work. Which operation does the missing RID Master eventually break?", options:["Kerberos ticket renewal for every user once current TGTs expire","Creating new security principals, once DCs exhaust their RID pools","Time synchronization across the domain, which Kerberos depends on","Schema extensions such as the LAPS update, which need the RID Master"], answer:1, why:"The RID Master hands each DC pools of 500 relative IDs so new SIDs never collide. Other DCs keep creating security principals until their pools run out, then creation fails. Time belongs to the PDC Emulator and schema changes to the Schema Master."},
 {id:"p16m4q4", q:"In a single domain, 12 finance staff need Modify on \\\\fs01\\finance. Which setup follows AGDLP?", options:["Add the 12 user accounts directly to the folder's NTFS ACL","Move the users into OU=Finance and grant that OU Modify on the folder","Users into a domain local group, that into a global group, Modify to the global group","Users into GG-Finance, GG-Finance into DL-FS-Finance-RW, Modify to DL-FS-Finance-RW"], answer:3, why:"AGDLP puts Accounts in Global groups by role, Global groups in Domain Local groups by resource, and grants Permissions to the Domain Local group. OUs cannot be granted access; they link policy and delegate administration. The reversed nesting breaks the pattern."},
 {id:"p16m4q5", q:"A DC VM was reverted to last week's snapshot on a hypervisor without VM-Generation ID support. Its replication partners now silently ignore the new changes it makes. What happened, and what is the correct practice?", options:["Its tombstones expired; enable the AD Recycle Bin and wait","The KCC has not rebuilt the topology yet; wait 15 minutes","USN rollback; restore DCs only from system-state backups","The inter-site interval is 180 minutes; the changes will arrive later"], answer:2, why:"Partners track each DC's update sequence numbers with high-watermarks, so reused USNs look already processed and are skipped forever. The damaged DC must be rebuilt; prevention is system-state backup instead of snapshots. Waiting for the KCC or the replication interval changes nothing."}
],
"p16m5":[
 {id:"p16m5q1", q:"You are about to turn on your first Conditional Access policy: require MFA for all users on all cloud apps. Which rollout avoids locking the tenant out?", options:["Enable it immediately for everyone, including every administrator","Exclude all administrators permanently so they can never be blocked","Turn on Security Defaults at the same time as a fallback","Run it in report-only mode first and exclude two emergency break-glass accounts"], answer:3, why:"Report-only mode shows who would be blocked before anything is enforced, and two excluded break-glass accounts guarantee a way back in if a policy misfires. Excluding all admins permanently leaves the most valuable accounts unprotected; Security Defaults is the free alternative to Conditional Access, not a companion."},
 {id:"p16m5q2", q:"A firm has 400 domain-joined desktops that depend on Group Policy and on-premises apps, and is buying 50 new laptops for fully remote staff. Which join states fit Microsoft's guidance?", options:["Hybrid join the existing desktops; Entra join the new laptops with Intune","Hybrid Entra join for all 450 devices, since it is the modern end state","Entra registered for all 450 devices, managed through Intune","Entra join for the desktops; Entra registered for the new laptops"], answer:0, why:"Hybrid join keeps Group Policy working on the existing domain fleet while adding Conditional Access, but it is the bridge, not the target. New corporate hardware should be Entra joined and Intune managed. Entra registered is meant for personal BYOD devices."},
 {id:"p16m5q3", q:"Requirements: cloud sign-ins must keep working if the on-premises domain controllers or the site's internet link go down, and you want leaked-credential detection. Which sign-in method fits?", options:["Pass-through authentication","Password hash synchronization","Federation through AD FS","Pass-through authentication with two agents on one domain controller"], answer:1, why:"With PHS a salted, iterated hash of the on-premises hash lives in Entra ID, so the cloud can authenticate on its own and check credentials against leaks. Pass-through authentication and AD FS both validate against on-premises infrastructure in real time, so they fail when it is unreachable."},
 {id:"p16m5q4", q:"A reseller should install the 6 GB of device-targeted apps before shipping, so that each user's own setup takes only minutes after sign-in. Which Autopilot mode is this?", options:["User-driven mode","Self-deploying mode","Pre-provisioning","Autopilot for existing devices"], answer:2, why:"Pre-provisioning lets IT or the reseller run the device phase in advance, started by pressing the Windows key five times, so the user phase is short. Self-deploying has no user at all and suits kiosks; user-driven does all the work after the user signs in."},
 {id:"p16m5q5", q:"Administrators were tricked by a fake sign-in page that relayed their passwords and one-time codes to the real site in real time. Which MFA requirement for admins stops this?", options:["Microsoft Authenticator push with number matching","SMS codes with a shorter expiry","Voice-call verification","Passkeys (FIDO2) or Windows Hello for Business"], answer:3, why:"Passkeys and Windows Hello sign a challenge with a device-bound key tied to the genuine service, so a look-alike page gets nothing it can reuse. Number matching defeats push-fatigue spam but not a proxy page that shows the victim the number; SMS and voice codes can be relayed directly."}
],
"p16m6":[
 {id:"p16m6q1", q:"A domain controller writes about 80 security events per second at roughly 500 bytes each. How long would a 192 MB Security log last before it wraps?", options:["About 8 minutes","About 13 hours","About 80 minutes","About 5 days"], answer:2, why:"80 × 500 bytes = 40 KB per second, and 192 MB / 40 KB/s = 4,800 s, about 80 minutes (roughly 3.5 GB a day). That is why DCs get a gigabyte or more of log and forward events off the box to a SIEM."},
 {id:"p16m6q2", q:"A database server feels slow. Counters: Processor 35%, Available MBytes 600 of 32,768, Pages/sec very high, and Avg. Disk sec/Transfer 25 ms on the disk holding the page file. What is the root cause?", options:["Memory pressure: heavy paging is what is loading the disk","Slow storage: replace the disk, since 25 ms exceeds the 20 ms threshold","A CPU-bound workload: add vCPUs to the server","Network saturation: check Bytes Total/sec on the NIC"], answer:0, why:"600 MB free is under 2% of RAM, far below the 10% guideline, and high Pages/sec shows heavy paging, which is what loads the page-file disk. Replacing the disk treats the symptom, and CPU at 35% is not the bottleneck."},
 {id:"p16m6q3", q:"Intune encrypts laptops with BitLocker, but no recovery escrow was configured. After a firmware update, a laptop demands its recovery key and nobody has it. Which two changes would have prevented this?", options:["Switch to XTS-AES 256 instead of 128, and add a pre-boot PIN to every laptop","Disable the TPM so only the PIN is checked, and turn off Secure Boot","Turn off BitLocker on laptops and rely on the Windows logon password instead","Escrow the recovery key before encrypting, and suspend BitLocker for firmware updates"], answer:3, why:"Suspending BitLocker for one reboot lets firmware change without tripping the TPM's boot-chain check, and an escrowed 48-digit recovery password turns a recovery prompt into an inconvenience instead of a wiped laptop. A stronger cipher does nothing for key recovery."},
 {id:"p16m6q4", q:"A 600-laptop company is fully cloud-managed with Intune and has no on-premises servers. It wants pilot-first patching. Which design fits best?", options:["Build a WSUS server and approve updates manually each month","Windows Update for Business rings: 1% day 0, 10% day 3, all by day 7","One ring for all devices with no deferral, so everyone patches on Patch Tuesday","Defer quality updates by 365 days so other companies find the problems first"], answer:1, why:"Update rings pull from Microsoft, need no on-premises server and stage the risk so a bad update hits a few pilots first. WSUS is deprecated and needs on-premises infrastructure; quality deferral tops out at 30 days, and 365 is the feature-update limit."},
 {id:"p16m6q5", q:"Yesterday an administrator deleted an OU containing 40 users. The AD Recycle Bin is enabled. What is the best first recovery step?", options:["Restore the OU and its objects from the AD Recycle Bin","Revert a DC to last night's VM snapshot","Perform an authoritative restore with ntdsutil in Directory Services Restore Mode","Recreate the 40 accounts by hand with the same names"], answer:0, why:"The Recycle Bin restores deleted objects with their SIDs, group memberships and attributes intact, without taking a DC offline. Authoritative restore is for when the Recycle Bin cannot help, a snapshot revert risks USN rollback, and recreated accounts get new SIDs, breaking existing permissions."}
],
"p16m7":[
 {id:"p16m7q1", q:"To fix a printer GPO quickly, Ana signs in to a help-desk workstation over RDP with her Tier 0 account ana-t0. Why is this the core violation of the tier model, and what prevents it?", options:["RDP sends credentials unencrypted; require TLS for every RDP session","Tier 0 accounts may not edit GPOs; she should have used a Tier 2 account","It is acceptable if she signs out quickly, since credentials leave LSASS at sign-out","Tier 0 credentials now sit in a Tier 2 LSASS; deny such logons by GPO and use a PAW"], answer:3, why:"Credentials must never flow down: an interactive logon leaves credential material in LSASS on that workstation, where any compromise of it can harvest a Tier 0 credential. Deny logon locally and through Remote Desktop for Tier 0 accounts on lower-tier OUs, and do Tier 0 work from a PAW."},
 {id:"p16m7q2", q:"The SIEM shows one standard user account requesting 4769 service tickets for 140 different SPNs in three minutes, all with ticket encryption type 0x17. What does this most likely indicate, and what reduces the risk?", options:["Normal behavior: users request tickets constantly, so no action is needed","Service-ticket harvesting; use gMSA or long random passwords and AES only","Password spraying across accounts; lower the lockout threshold","A non-DC replicating the directory; investigate 4662 events"], answer:1, why:"0x17 is RC4, and requesting tickets for many SPNs within minutes is not normal user behavior. Tickets keyed with a service account's password can be attacked offline, so gMSA or long random passwords and AES-only Kerberos make them worthless. Spraying shows as 4625 or 4771, not 4769."},
 {id:"p16m7q3", q:"Sysmon on a laptop logs event 1 with ParentImage EXCEL.EXE and Image cmd.exe, followed by powershell.exe with -EncodedCommand. Which preventive control would have stopped the first step?", options:["BitLocker with a pre-boot PIN, so the disk stays encrypted","Windows LAPS, so every local Administrator password is unique","The ASR rule blocking Office apps from creating child processes","Credential Guard, so LSASS secrets sit in an isolated container"], answer:2, why:"The chain starts with Excel spawning a shell, which is exactly what that ASR rule blocks. Credential Guard protects LSASS secrets later in the chain, LAPS removes shared local administrator passwords, and BitLocker protects data on a lost, powered-off device."},
 {id:"p16m7q4", q:"PingCastle flags svc-sql: it has an SPN, a 12-character password unchanged since 2019, RC4 allowed, and membership in Domain Admins. Which remediation addresses the weakness?", options:["Move it to a gMSA with AES only and remove it from Domain Admins","Enable account lockout after 5 failed attempts on the account","Rename the account and hide its SPN so it is harder to find","Add it to Protected Users and leave it in Domain Admins"], answer:0, why:"The risk is a weakly keyed service ticket that can be attacked offline and leads straight to Tier 0. A gMSA or long random password with AES-only encryption fixes the key, and leaving Domain Admins removes the path. Lockout cannot help, because offline guessing never touches the DC."},
 {id:"p16m7q5", q:"A small-business owner says on the phone, 'Sure, check how secure our AD is,' and you plan to run BloodHound Community Edition and PingCastle on their network next week. What must exist before you start?", options:["Nothing more; the owner's verbal OK is enough for read-only tools","Only a signed nondisclosure agreement with the owner","Approval from their internet service provider","Written authorization and scope from someone with authority"], answer:3, why:"Accessing systems you do not own without written authorization can be a crime under the Computer Fraud and Abuse Act, whatever the tool. The written scope also fixes what is in bounds, when, and whom to call. Read-only tools still access the systems, and an NDA covers confidentiality, not legality."}
]
});
Object.assign(window.LQ,{
"p17m1":[
 {id:"p17m1q1", q:"A Lambda function's execution environment needs a kernel security patch, and the same function's IAM role allows s3:* on every bucket in the account. Under the shared responsibility model, who handles each?", options:["AWS handles both, because Lambda is fully managed","You handle both, because the function is your code","AWS patches the kernel; you must narrow the role to least privilege","You patch the kernel; AWS reviews the role's permissions"], answer:2, why:"With serverless, the provider owns the OS, the host and the hypervisor, so kernel patches are AWS's job. Your code, configuration and IAM permissions stay yours under every service model, so the over-broad role is your fix. Fully managed never covers your identities."},
 {id:"p17m1q2", q:"An on-premises server costs $3,600, depreciated over five years, and draws 200 W around the clock at $0.13/kWh. Using 730 hours a month, about what does it cost per month before rack space and labor?", options:["About $79","About $60","About $19","About $146"], answer:0, why:"Hardware: $3,600 / 60 months = $60. Power: 200 W × 730 h = 146 kWh × $0.13 ≈ $19. Together about $79 a month, before cooling, a UPS, a static IP and your time. Leaving out electricity gives the tempting $60."},
 {id:"p17m1q3", q:"Three accounts each have a VM someone forgot to stop: (a) an AWS Free plan account, never upgraded, whose credit is used up; (b) an Azure account upgraded to pay-as-you-go after its 30-day trial; (c) a Google Cloud account upgraded after its 90-day trial. Which can bill a card?", options:["All three","None, because free tiers never charge a card","Only (a)","Only (b) and (c)"], answer:3, why:"AWS's Free plan cannot charge until you explicitly upgrade; when the credit or the six months runs out, it stops instead of billing. Upgraded Azure and Google accounts are real meters that bill a forgotten VM indefinitely, which is why a billing alarm or budget comes first."},
 {id:"p17m1q4", q:"Users in Lima complain that images on your site, served from an EC2 instance in us-east-1, load slowly. Which change most directly cuts that latency?", options:["Add a second Availability Zone in us-east-1 for capacity","Serve the images through CloudFront edge locations","Move to a larger instance size with more network bandwidth","Switch the instance to a faster Graviton type"], answer:1, why:"The delay is distance: every image request crosses thousands of kilometers to Virginia. A CDN caches content at points of presence close to the users, so repeat requests never travel that far. Another AZ or a bigger instance changes nothing about the distance."},
 {id:"p17m1q5", q:"You move a MySQL database from a self-managed EC2 instance to Amazon RDS. Under the shared responsibility model, which duty moves from you to the provider?", options:["Deciding which database users get which privileges","Writing the security group rules that admit the app servers","Patching the operating system and the database engine","Choosing whether the data is encrypted"], answer:2, why:"RDS is PaaS: the provider takes over the OS, engine patches, backups and failover machinery. Database users, network rules and the encryption choice stay with you, because data and access decisions remain the customer's under every service model."}
],
"p17m2":[
 {id:"p17m2q1", q:"A Lambda function (x86, 1,024 MB) runs 300 ms per invocation, 2 million times a month. Including the permanent free tier of 1 million requests and 400,000 GB-seconds, what is the monthly bill?", options:["About $3.53","About $10.40","About $0.20","About $6.67"], answer:0, why:"2,000,000 × 0.3 s × 1 GB = 600,000 GB-s; minus 400,000 free leaves 200,000 × $0.0000166667 ≈ $3.33. Requests: 1 million billable × $0.20 = $0.20. Total about $3.53. Ignoring the free tier gives $10.40."},
 {id:"p17m2q2", q:"A video transcoder that runs flat out around the clock was placed on a t3.large in standard credit mode. It is fast for the first hour, then slows to a crawl. What is happening, and what fits better?", options:["The instance is simply too small; move up to a t3.2xlarge","EBS is throttling the job's disk writes; switch to instance store","Its CPU credits ran out; use a compute-optimized c-family instance","The hypervisor deprioritizes long jobs; use a spot instance"], answer:2, why:"Burstable t instances earn credits while idle and spend them in bursts; a constant CPU-bound load drains them and the instance falls back to its baseline. A bigger t size only delays the drain, while a compute-optimized family delivers full CPU continuously."},
 {id:"p17m2q3", q:"A service needs 10 instances 24/7 all year, up to 15 more during unpredictable spikes, and a nightly batch job that can be interrupted and resumed. Which purchasing mix is cheapest without risking the service?", options:["A one-year Savings Plan sized for all 25 peak instances","Savings Plan for the baseline, on demand for spikes, spot for the batch","Spot for everything, since spot is the cheapest compute available","On demand for everything, to stay flexible as load changes"], answer:1, why:"Commit only to the baseline you know you will run, buy the unpredictable part on demand, and put interruptible work on spot with its two-minute warning. Committing to the peak pays for idle capacity; running the steady service on spot risks reclaims during traffic."},
 {id:"p17m2q4", q:"An Auto Scaling group with minimum and desired capacity 6 spreads its instances evenly across three AZs behind an ALB. One AZ fails. What happens?", options:["All six instances stop, since the group lives in one AZ","Nothing changes until an operator replaces the instances manually","The ALB keeps sending traffic to the dead instances until the AZ recovers","Two are lost; the group replaces them in the healthy AZs"], answer:3, why:"Spreading across three AZs means an AZ failure costs a third of the fleet, not all of it. ALB health checks stop routing to the failed targets, and the Auto Scaling group restores the desired count in the healthy AZs automatically."},
 {id:"p17m2q5", q:"An API runs at about 60% CPU around the clock on a VM costing $0.067/hour under a Savings Plan. A colleague proposes Lambda instead: 50 million requests a month, 200 ms each at 1 GB. Which is cheaper?", options:["The VM: about $49 a month against about $170 for Lambda","Lambda: about $17 a month, since it scales to zero","Lambda, because serverless is always cheaper than a VM","The VM: about $49 a month against about $1,700 for Lambda"], answer:0, why:"Lambda: 50M × 0.2 s × 1 GB = 10,000,000 GB-s, minus 400,000 free, is 9.6M × $0.0000166667 ≈ $160, plus 49M requests at $0.20 per million ≈ $10: about $170. The VM is 730 × $0.067 ≈ $49. Sustained load favors the flat rate."}
],
"p17m3":[
 {id:"p17m3q1", q:"A bucket has versioning on and holds 200 GB in S3 Standard ($0.023/GB-month). A nightly job overwrites all 200 GB, and no rule expires noncurrent versions. After 30 days, about what is the storage bill heading toward?", options:["About $4.60 a month, because overwrites replace the objects","About $143 a month, because every overwrite keeps the old version","About $9.20 a month, because versioning keeps exactly one previous copy","About $143 a month, because S3 charges heavily for every PUT request"], answer:1, why:"Each night adds 200 GB of noncurrent versions, so after 30 days about 6,200 GB is stored: 6,200 × $0.023 ≈ $143. A lifecycle rule expiring noncurrent versions keeps the recovery benefit without the growth. PUT charges are fractions of a cent per thousand."},
 {id:"p17m3q2", q:"Reporting queries are slowing a production RDS MySQL instance. The team enabled a Multi-AZ instance deployment (one standby) to offload them, and nothing improved. Why, and what should they do?", options:["Multi-AZ needs 24 hours of sync before it serves reads; wait","Read offloading via Multi-AZ only works on Aurora; migrate first","The standby is undersized; give it a larger instance class","The standby serves no reads; add a read replica for the reports"], answer:3, why:"A Multi-AZ instance deployment keeps a synchronous standby that takes over on failure but accepts no queries. Read replicas are asynchronous copies built for scaling reads, so reporting traffic belongs there. Confusing the two is a classic exam trap."},
 {id:"p17m3q3", q:"Data on a gp3 EBS volume attached to an instance in us-east-1a must be used by a new instance in us-east-1b. What is the correct approach?", options:["Snapshot it, then create a volume from the snapshot in us-east-1b","Detach the volume and attach it to the instance in us-east-1b","Mount the volume over NFS from the second AZ","Convert the volume to instance store, which can move between AZs"], answer:0, why:"An EBS volume lives in one AZ and can attach only to instances there. A snapshot is stored in S3, so a new volume can be created from it in any AZ of the Region. Instance store is local to the host and vanishes when the instance stops."},
 {id:"p17m3q4", q:"Workload A is a session store: 20,000 writes per second, lookups only by session ID, 2 KB items, single-digit-millisecond reads. Workload B is monthly finance reporting that joins 12 tables with ad hoc queries. Which pairing fits?", options:["RDS for A; DynamoDB for B","S3 for A; ElastiCache for B","DynamoDB for A; RDS or Aurora for B","DynamoDB for both, since it scales further"], answer:2, why:"Key-based access at huge write volume with predictable millisecond latency is what DynamoDB is built for. Joins across many tables, transactions and ad hoc queries need a relational engine. NoSQL drops joins, so forcing B into DynamoDB means rewriting every report."},
 {id:"p17m3q5", q:"A manager argues: 'S3 has eleven nines of durability, so we don't need backups.' Which threat does durability not cover, and what does?", options:["Disk failure in one AZ; spread the bucket across more Availability Zones","Deletion with stolen keys; versioning, Object Lock, cross-account copies","A full Regional outage; Cross-Region Replication alone covers it","Silent bit rot; S3 Intelligent-Tiering re-checks and covers it"], answer:1, why:"Eleven nines protects against hardware loss across AZs, not against a valid but wrong or malicious delete. Versioning keeps old versions, Object Lock makes them immutable, and a copy in an account the attacker cannot reach survives a compromised account. Replication alone does not stop someone who controls both buckets."}
],
"p17m4":[
 {id:"p17m4q1", q:"A VPC is 10.30.0.0/16 and you carve it into /26 subnets. How many usable host addresses does each AWS subnet have, and how many /26 subnets fit in the VPC?", options:["62 usable; 1,024 subnets","59 usable; 256 subnets","64 usable; 512 subnets","59 usable; 1,024 subnets"], answer:3, why:"A /26 holds 64 addresses and AWS reserves five (network, router, DNS, one spare, broadcast), leaving 59. A /16 contains 2^(26 − 16) = 2^10 = 1,024 /26 blocks. Subtracting only two, as on a traditional LAN, gives the tempting 62."},
 {id:"p17m4q2", q:"An instance in a subnet with 'auto-assign public IP' enabled has a public address, and its security group allows SSH from your IP, yet you cannot reach it. The subnet's route table has only the local route. What fixes it?", options:["Attach an Elastic IP, since auto-assigned addresses are not routable","Add 0.0.0.0/0 pointing to the internet gateway in its route table","Add an outbound rule for port 22 to the security group","Place a NAT gateway in the subnet to carry the SSH traffic"], answer:1, why:"A subnet is public only when its route table sends 0.0.0.0/0 to an internet gateway; a public IP without that route reaches nothing. Security groups are stateful, so replies need no outbound rule, and a NAT gateway allows outbound connections only, never inbound."},
 {id:"p17m4q3", q:"A custom network ACL on the web subnet allows inbound TCP 443 from 0.0.0.0/0 and outbound TCP 443 to 0.0.0.0/0, and nothing else. The security group is correct. Clients' HTTPS connections hang. Why?", options:["Network ACLs cannot filter HTTPS, so remove the 443 rules","The security group must also allow outbound 443 to clients","The ACL is stateless; allow outbound to ephemeral ports 1024–65535","A NACL's lowest-numbered rule must be a deny for allows to work"], answer:2, why:"A network ACL does not track connections, so return traffic is judged as new traffic. Server responses leave port 443 for the client's ephemeral port, typically 1024–65535, which this ACL drops. Security groups are stateful and need no matching outbound rule."},
 {id:"p17m4q4", q:"Private instances push 3 TB a month of backups to S3 through a NAT gateway that charges $0.045 per GB processed. What does that traffic cost, and what is the fix?", options:["About $135 a month; add an S3 gateway endpoint, which is free","About $13.50 a month; not worth changing","About $135 a month; move the instances into public subnets","About $270 a month; add a second NAT gateway to halve the charge"], answer:0, why:"3,000 GB × $0.045 = $135 a month in processing fees alone. A gateway endpoint for S3 routes that traffic privately at no charge and keeps it off the internet. Moving servers into public subnets saves money by weakening security, and a second NAT gateway only adds cost."},
 {id:"p17m4q5", q:"Your crew is patching a 10 Gbps dedicated Direct Connect cross-connect in a colocation facility. A tech arrives with 10GBASE-SR optics and OM4 multimode jumpers. What does the connection actually require?", options:["Nothing different; any 10 Gbps optic will link at that speed","OM4 is fine if the run is under 300 m, since AWS accepts SR optics","Copper DAC cables run directly to the AWS router","Single-mode fiber with 10GBASE-LR (1310 nm) optics, 802.1Q and BGP"], answer:3, why:"AWS specifies single-mode fiber with 10GBASE-LR 1310 nm optics for 10 Gbps dedicated connections, with 802.1Q tagging and MD5-authenticated BGP above it. Multimode SR optics will not match the AWS-side port, however short the run."}
],
"p17m5":[
 {id:"p17m5q1", q:"A user's only policy allows s3:* on arn:aws:s3:::reports-2026/*. Which calls succeed: listing all buckets (aws s3 ls), listing this bucket's contents, and getting or putting objects in it?", options:["Only getting and putting objects; both listing calls are denied","All of them, because s3:* includes every S3 action","Only listing the bucket's contents","Listing works, but object access is denied because the bucket ARN lacks /*"], answer:0, why:"The resource with /* matches objects only. Listing a bucket's contents (ListBucket) needs the bucket ARN without /*, and listing all buckets (ListAllMyBuckets) needs resource *. Policy grammar is literal: s3:* names the actions, but the resource still limits where they apply."},
 {id:"p17m5q2", q:"A developer's identity policy allows ec2:RunInstances on all resources. The Organization's service control policy denies every action outside us-east-1 and us-west-2. The developer launches an instance in eu-west-1. What happens?", options:["It succeeds, because the identity policy explicitly allows it","It succeeds, because SCPs apply only to the root user","It is denied, because the SCP's explicit deny overrides the Allow","It is denied only if a permissions boundary also exists"], answer:2, why:"A request must be allowed at every layer: identity or resource policy, service control policies and any permissions boundary, and an explicit deny anywhere wins. The SCP denies eu-west-1, so the identity Allow never takes effect. SCPs bind all principals in member accounts, not just root."},
 {id:"p17m5q3", q:"An analyst's IAM policy allows s3:GetObject on a bucket whose objects are encrypted with SSE-KMS under a customer-managed key. The key policy does not let the analyst use the key. What happens on GetObject?", options:["It succeeds, because S3 permissions alone decide access to S3 objects","It succeeds, but returns the encrypted bytes for the analyst to decrypt locally","It succeeds, because SSE-KMS keys are shared across the account","AccessDenied, because the analyst lacks kms:Decrypt on the key"], answer:3, why:"With envelope encryption, reading the object means asking KMS to decrypt its data key, and the key policy decides who may do that independently of IAM. Without kms:Decrypt the request is denied: the bucket is readable in theory and unreadable in practice."},
 {id:"p17m5q4", q:"With written authorization covering a client's AWS account, the client asks you to scan their EC2 instances for vulnerabilities and to check whether their login endpoint behind their own ALB survives 10,000 login attempts per second. What does AWS policy allow?", options:["Both, because the client owns the resources and authorized you","Only the EC2 vulnerability scan; login flooding is prohibited","Neither, because every test on AWS needs prior approval","Only the login flood, because scanning is reserved for Amazon Inspector"], answer:1, why:"AWS permits assessments of listed services such as EC2 and Elastic Load Balancing on authorized resources without approval, but forbids denial of service and request flooding, including login flooding, regardless of who owns the target. The client's consent cannot override the provider's terms."},
 {id:"p17m5q5", q:"GuardDuty reports that an EC2 instance role's temporary credentials are being used from an external IP that is not the instance, and CloudTrail shows ListBuckets and GetObject calls from that IP. What is the right first response?", options:["None; temporary credentials expire within hours, so the issue resolves itself","Replace the role with an IAM user whose access keys are stored on the server","Revoke the role's sessions, require IMDSv2, and trace the leak","Rotate the root account password and keep monitoring"], answer:2, why:"Stolen session credentials stay valid until they expire, and fresh ones can be stolen while the leak persists. Revoke existing sessions, close the likely path (IMDSv1 reachable through request forgery) and find the root cause. Long-term access keys on the server would make a future leak permanent."}
],
"p17m6":[
 {id:"p17m6q1", q:"A shop runs an ALB (99.99%) in front of a web tier spread over two independent AZs (each 99.9%), then a database at 99.95%. Roughly what is the end-to-end availability?", options:["About 99.9999%, because the best component sets the total","About 99.74%, because the two web AZs multiply in series","About 99.94%, roughly 5.3 hours of downtime a year","About 99.95%, because only the database matters"], answer:2, why:"The parallel web tier fails only if both AZs fail: 1 − 0.001 × 0.001 = 99.9999%. The chain then multiplies in series: 0.9999 × 0.999999 × 0.9995 ≈ 99.94%, and 0.06% of 8,760 hours is about 5.3 hours. Treating the two AZs as a series chain is the classic error."},
 {id:"p17m6q2", q:"Two copies of an app run on two servers in the same rack in one AZ, each 99.9% available. A colleague computes 1 − 0.001² = 99.9999% for the pair. What is wrong?", options:["It assumes independent failures, but a shared rack and AZ fail together","Nothing; parallel copies always multiply their unavailabilities","Parallel availabilities must be averaged, giving 99.9% for the pair","The two copies should be multiplied in series, giving 99.8%"], answer:0, why:"Multiplying failure probabilities is valid only when failures are independent. Copies in one rack share power, a top-of-rack switch and the AZ, so one event takes out both. That is exactly why AZs are separate buildings on separate power."},
 {id:"p17m6q3", q:"An upload page calls the thumbnail service synchronously; when thumbnailing slows down, uploads hang and time out. Which redesign decouples them properly?", options:["Give the thumbnail service a larger instance type so it keeps up","Put an SQS queue between them and scale workers on queue depth","Have the upload page retry the synchronous call with exponential backoff","Run a second copy of the thumbnail service in another Region"], answer:1, why:"A queue lets the upload succeed immediately while workers absorb bursts at their own pace, and scaling on queue depth matches the fleet to the backlog; add a dead-letter queue for poison messages. Bigger instances and retries leave the two services failing together."},
 {id:"p17m6q4", q:"Each night 3,000 files need 30 minutes of single-vCPU work each. On c7g.xlarge spot instances (4 vCPU, about $0.06/hour), roughly what does a night cost?", options:["About $90","About $5.63","About $180","About $22.50"], answer:3, why:"3,000 × 0.5 h = 1,500 vCPU-hours. Each instance supplies 4 vCPUs, so 375 instance-hours × $0.06 = $22.50. Forgetting to divide by the 4 vCPUs prices every vCPU-hour as a whole instance-hour and gives $90."},
 {id:"p17m6q5", q:"An Aurora database must lose at most 5 minutes of data if its whole Region fails. Which option meets that RPO?", options:["Aurora Global Database, with typically sub-second cross-Region lag","Aurora's six storage copies spread across three AZs of the Region","Daily automated snapshots, each copied to another Region","An Aurora read replica in another AZ of the same Region"], answer:0, why:"Only cross-Region replication protects against losing the Region, and Global Database keeps lag under a second, well inside 5 minutes. Six copies across AZs and same-Region replicas all fail with the Region, and daily snapshots allow up to a day of loss."}
],
"p17m7":[
 {id:"p17m7q1", q:"In a lab account you want new EC2 launches blocked automatically once monthly spend reaches $50. Which guardrail does that?", options:["A CloudWatch billing alarm that emails you through SNS","A Budgets action that applies an IAM deny on ec2:RunInstances","A daily Cost Explorer report filtered to EC2 spending","A tag policy requiring Project and Owner tags on instances"], answer:1, why:"A budget action can apply an IAM or service control policy when a threshold is crossed, so it acts instead of merely warning. A billing alarm only notifies, Cost Explorer reports after the fact, and tag policies attribute cost but never stop spending."},
 {id:"p17m7q2", q:"Someone hand-edited a security group that your CloudFormation stack created, and you are about to update the stack's template. Which features reveal the hand edit and preview the update before it runs?", options:["CloudTrail shows the edit; terraform plan previews the update","AWS Config shows the edit; a stack rollback previews the update","CloudWatch dashboards show the edit; a new stack previews the update","Drift detection shows the edit; a change set previews the update"], answer:3, why:"Drift detection compares live resources with the template and reports manual changes; a change set lists what an update would add, modify or replace before you execute it. terraform plan is Terraform's equivalent of a change set, not a CloudFormation feature."},
 {id:"p17m7q3", q:"aws s3 ls runs fine but lists buckets you do not recognize. You use several named profiles. What is the quickest check?", options:["Delete ~/.aws/credentials and configure every profile again","Reinstall the AWS CLI v2 to clear its cached session","Run aws sts get-caller-identity to see which identity is in use","Open CloudShell and compare the bucket lists by eye"], answer:2, why:"get-caller-identity returns the account ID and ARN behind the current credentials, exposing a default profile or environment variable that points at the wrong account. Then choose --profile or AWS_PROFILE deliberately. Deleting credentials destroys working configuration and tells you nothing."},
 {id:"p17m7q4", q:"You want a CloudWatch alarm on memory usage for an EC2 instance, but no memory metric exists to select. Why?", options:["The hypervisor cannot see guest memory; install the CloudWatch agent","Memory metrics appear only after enabling paid detailed monitoring","Memory metrics are published only in the us-east-1 Region","The instance must be stopped before memory metrics are collected"], answer:0, why:"EC2's built-in metrics come from the hypervisor, which sees CPU, network and disk but not how the guest OS uses its RAM. The CloudWatch agent inside the instance publishes memory and disk-space metrics. Detailed monitoring only raises the frequency to one minute."},
 {id:"p17m7q5", q:"Classify these home-lab items with the 7 Rs: (a) a GPU box running local models 24/7, (b) a static portfolio site, (c) an unused Minecraft server, (d) a MySQL-backed app moving to RDS.", options:["(a) rehost, (b) retain, (c) retire, (d) refactor","(a) retain, (b) refactor, (c) retire, (d) replatform","(a) refactor, (b) rehost, (c) retain, (d) replatform","(a) retain, (b) rehost, (c) repurchase, (d) refactor"], answer:1, why:"A 24/7 GPU costs more to rent than to own, so it stays home (retain); the site is rebuilt serverless on S3 and CloudFront (refactor); unused things are retired; the same app on a managed database is replatforming. Lifting the GPU box into EC2 is the costly mistake."}
]
});
